from pathlib import Path
import json,html,subprocess
R=Path(__file__).resolve().parents[1];r=R/'runs';manifest=json.load(open(r/'yabuuchi-batch-manifest.json'))
cs=[]
for item in manifest['items']:
 version='v4' if item['slug'] in ['churrasco-roll','quiero-dos','la-baby'] else 'v3'
 name='yabuuchi-'+item['slug']+'-'+version;p=r/(name+'.mp4')
 if not p.exists():continue
 report=json.load(open(r/(name+'.json')));dur=report['verification']['duration']
 if not (r/(name+'-poster.jpg')).exists():subprocess.run(['ffmpeg','-v','error','-ss','1','-i',str(p),'-frames:v','1','-vf','scale=432:768',str(r/(name+'-poster.jpg'))],check=True)
 notes={'sin-pescado-crudo':'Confirmar la palabra dumplings en la última frase.','otro-rollo':'Confirmar la frase final con el audio.','elige-tu-favorito':'Revisar nombres de platos y respuestas.','toa-baja':'Se usa la toma de ubicación sin horario; las versiones grabadas dan horarios distintos.','la-baby':'Revisar la primera frase.','calidad':'Revisar la última frase.','historia':'Confirmar nombres y datos de la historia con el cliente.'}.get(item['slug'],'Revisar voz, música y subtítulos antes de aprobar.')
 cs.append(f'''<article><video controls playsinline preload="metadata" poster="{name}-poster.jpg" src="{name}.mp4"></video><div><p class="meta">BORRADOR {version.upper()} · {dur:.1f} S</p><h2>{html.escape(item['title'])}</h2><p>{html.escape(notes)}</p><a href="{name}.mp4" download>Descargar Video</a><a href="{name}-compare.jpg" target="_blank">Ver Fotogramas</a></div></article>''')
held=''.join('<li>'+html.escape(x['reason'])+'</li>' for x in manifest['held'])
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yabuuchi Sushi · Revisión</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f6ef;color:#10332e;font:16px system-ui}header,main,footer{max-width:1180px;margin:auto;padding:26px}header{padding-top:44px}.eyebrow{font-size:12px;letter-spacing:.15em;font-weight:800}h1{font-size:clamp(32px,5vw,54px);letter-spacing:-.04em;margin:10px 0}header p{max-width:740px;line-height:1.6}.badge{display:inline-block;background:#dcf7aa;padding:8px 12px;border-radius:22px;font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}article{background:white;border:1px solid #dce3d5;border-radius:16px;overflow:hidden}video{width:100%;display:block;aspect-ratio:9/16;background:#0e201e;object-fit:contain}article>div{padding:18px}h2{font-size:21px;line-height:1.2;margin:8px 0}article p{font-size:13px;line-height:1.5;color:#486059}.meta{letter-spacing:.06em;font-weight:700;font-size:11px!important}button{background:#10332e;color:white;border:0;border-radius:8px;padding:12px 18px;font:inherit;cursor:pointer}#playstate{font-size:13px;margin-left:12px}a{display:inline-block;color:#10332e;font-size:13px;font-weight:700;padding:10px 0;margin-right:18px}details{margin:30px 0;background:#fff;padding:20px;border-radius:12px}li{margin:12px 0;line-height:1.5}footer{font-size:12px;color:#61736e}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){header,main,footer{padding:18px}.grid{grid-template-columns:1fr;gap:22px}article{max-width:420px;width:100%;margin:auto}}</style><header><p class="eyebrow">NATE MEDIA · YABUUCHI SUSHI</p><h1>Toa Baja, En Video.</h1><p>Grabación del 14 de septiembre. Edición basada en video 1.2.mp4: captions bajos, apoyos de producto, gráficas discretas y cierre de la referencia.</p><span class="badge">'''+str(len(cs))+''' Borradores · Revisión Pendiente</span><p>Los archivos pasan la comprobación de decodificación. La escucha crítica y la aprobación siguen pendientes. La tipografía aproxima la referencia aportada. Los sonidos son recreaciones, pendientes de comparación auditiva.</p></header><main><p><a href="yabuuchi-lote.html">Ver Lote Completo</a> <button id="batch">Reproducir Todos</button> <span id="playstate" role="status">Listos Para Revisar</span></p><section class="grid">'''+''.join(cs)+'''</section><details><summary>Material Pendiente Y Observaciones</summary><ul>'''+held+'''</ul></details></main><footer>Originales conservados · Sin publicación ni envío al cliente</footer><script>const vs=[...document.querySelectorAll('video')],st=document.getElementById('playstate');let queue=false;vs.forEach((v,i)=>{v.addEventListener('play',()=>vs.forEach(o=>{if(o!==v)o.pause()}));v.addEventListener('error',()=>{st.textContent='Error En Video '+(i+1);queue=false});v.addEventListener('ended',()=>{st.textContent='Reproducidos '+(i+1)+' De '+vs.length;if(queue&&i+1<vs.length){vs[i+1].currentTime=0;vs[i+1].play();vs[i+1].scrollIntoView({behavior:'smooth',block:'center'})}else queue=false})});document.getElementById('batch').onclick=()=>{queue=true;vs[0].currentTime=0;vs[0].play();vs[0].scrollIntoView({behavior:'smooth',block:'center'});st.textContent='Reproduciendo 1 De '+vs.length};</script></html>'''
(r/'yabuuchi-review.html').write_text(page)
print('Gallery:',len(cs))
